}

const ejercicio = readPositiveInteger(getVar('CAMPOJOYMA_EJERCICIO'));
if (!ejercicio) warnings.push('Falta CAMPOJOYMA_EJERCICIO; no se deriva desde el ano natural ni desde la fecha de factura.');

// ---------------------------------------------------------------- historico del proveedor
// Medido el 27/07/2026 sobre el ejercicio 25 (5.323 facturas):
//   regimen por proveedor+iva1 -> 99,3% ; por proveedor -> 98,2%
//   tipo de factura por proveedor -> 97,6%
// Se usa como SUGERENCIA con su denominador. Solo se rellena el campo cuando el
// historial del proveedor es unanime; en cualquier otro caso queda pendiente.
const ivaPrincipal = readNumber(literal.tramos_iva?.[0]?.porcentaje);
let historia = [];
let historiaTotal = null;
if (providerId && apiBase) {
  const histResult = await apiGetResult('/facturasrecibidas', {
    proveedor_id: providerId,
    limit: API_MAX_LIMIT,
    offset: 0,
  });
  if (histResult.ok) {
    historia = itemsFromResponse(histResult.data);
    historiaTotal = readInteger(histResult.data?.total, historia.length);
  }
}

// Umbral: se rellena el campo cuando el proveedor tiene al menos 5 facturas
// previas y el valor dominante cubre el 90%. Por debajo queda pendiente. Aun
// rellenado, el campo entra en requires_confirmation: es una sugerencia con su
// denominador visible, nunca un valor cerrado.
const MIN_MUESTRA = 5;
const MIN_CONFIANZA = 90;
const sugerirDesdeHistoria = (campo, filtro) => {
  const muestra = historia.filter((row) => filtro(row));
  const counts = new Map();
  for (const row of muestra) {
    const value = campo === 'tipo' ? readString(row.tipo_factura) : readPositiveInteger(row.regimen_id);
    if (value === null || value === undefined) continue;
    counts.set(value, (counts.get(value) ?? 0) + 1);
  }
  const ranking = [...counts.entries()].sort((a, b) => b[1] - a[1]);
  const total = ranking.reduce((sum, [, count]) => sum + count, 0);
  if (total === 0) return { value: null, aplicable: false, unanime: false, confianza: null, total: 0, ranking: [] };
  const [topValue, topCount] = ranking[0];
  const confianza = Math.round((topCount / total) * 1000) / 10;
  return {
    value: topValue,
    confianza,
    total,
    unanime: ranking.length === 1,
    aplicable: total >= MIN_MUESTRA && confianza >= MIN_CONFIANZA,
    ranking: ranking.slice(0, 4).map(([value, count]) => ({ value, count })),
  };
};

const tipoSugerido = sugerirDesdeHistoria('tipo', () => true);
const mismoIva = (row) => ivaPrincipal === null || Math.abs((readNumber(row.iva1) ?? -1) - ivaPrincipal) < 0.001;
const regimenPorPar = sugerirDesdeHistoria('regimen', mismoIva);
const regimenPorProveedor = sugerirDesdeHistoria('regimen', () => true);

// El regimen del ERP sigue a FRR_iva1, el PRIMER hueco de la escalera de IVA,
// que no siempre es el tipo que lleva la base imponible. Medido sobre las 120
// altas mas recientes: 21 de 120 (17,5%) tienen la base en un hueco distinto
// del 1. Ejemplos reales: proveedor 1469 con FRR_iva1=4% y la base al 21% en el
// hueco 3 recibe el regimen 2115 (el del 4%); proveedor 413 con FRR_iva1=21% y
// la base al 10% recibe 2110 (el del 21%).
//
// Desde un PDF no se puede reproducir en que hueco colocara el operador cada
// tipo, asi que el par (proveedor, IVA visible) no es reconstruible. Por eso el
// regimen solo se rellena cuando TODO el historial del proveedor coincide en un
// unico valor: ahi la colocacion de huecos es irrelevante.
const ivasEnHistoria = new Set(
  historia.map((row) => readNumber(row.iva1)).filter((value) => value !== null),
);
const proveedorMultiIva = ivasEnHistoria.size > 1;
const historiaDesalineada = historia.filter((row) => (readNumber(row.base1) ?? 0) === 0).length;
const regimenSugerido = {
  ...regimenPorProveedor,
  aplicable: regimenPorProveedor.unanime && regimenPorProveedor.total >= MIN_MUESTRA,
};

// Relleno de ultimo recurso, decidido con el cliente: ningun borrador sale con
// tipo o regimen vacios. Son los valores dominantes de Campojoyma (OT 78,5% y
// 2110 64,9% del ejercicio 25), pero solo se aplican cuando el historial del
// proveedor no da una respuesta mejor. Siempre entran en requires_confirmation.
const DEFAULT_TIPO_FACTURA = 'OT';
const DEFAULT_REGIMEN_ID = 2110;

const tipoVariable = readString(getVar('CAMPOJOYMA_TIPO_FACTURA'));
const regimenVariable = readPositiveInteger(getVar('CAMPOJOYMA_REGIMEN_ID'));

let tipoFactura = null;
let tipoOrigen = 'pending';
if (tipoVariable) {
  tipoFactura = tipoVariable;
  tipoOrigen = 'n8n_variable';
} else if (tipoSugerido.aplicable) {
  tipoFactura = tipoSugerido.value;
  tipoOrigen = tipoSugerido.unanime ? 'historico_unanime' : 'historico_mayoritario';
  requiresConfirmation.push('FRR_tipofactura');
} else {
  tipoFactura = DEFAULT_TIPO_FACTURA;
  tipoOrigen = 'default_campojoyma';
  requiresConfirmation.push('FRR_tipofactura');
  warnings.push('FRR_tipofactura se rellena con el default ' + DEFAULT_TIPO_FACTURA
    + ' porque el historial del proveedor no alcanza ' + MIN_CONFIANZA + '% con al menos '
    + MIN_MUESTRA + ' facturas (observado ' + (tipoSugerido.confianza ?? 0) + '% sobre '
    + tipoSugerido.total + '). Requiere confirmacion.');
}

let regimenId = null;
let regimenOrigen = 'pending';
if (regimenVariable) {
  regimenId = regimenVariable;
  regimenOrigen = 'n8n_variable';
} else if (regimenSugerido.aplicable) {
  regimenId = regimenSugerido.value;
  regimenOrigen = 'historico_proveedor_unanime';
  requiresConfirmation.push('FRR_idregimen');
} else {
  regimenId = DEFAULT_REGIMEN_ID;
  regimenOrigen = 'default_campojoyma';
  requiresConfirmation.push('FRR_idregimen');
  warnings.push('FRR_idregimen se rellena con el default ' + DEFAULT_REGIMEN_ID + ' porque '
    + (proveedorMultiIva
      ? 'el proveedor usa ' + ivasEnHistoria.size + ' tipos de IVA distintos en el hueco 1 y el regimen sigue a ese hueco, que no se puede deducir del PDF'
      : 'el historial del proveedor no es unanime o no llega a ' + MIN_MUESTRA + ' facturas')
    + ' (dominante ' + (regimenSugerido.confianza ?? 0) + '% sobre ' + regimenSugerido.total + '). Requiere confirmacion.');
}

// ---------------------------------------------------------------- fecha contable
// Medido sobre las 120 altas mas recientes: fechactb == fechafactura solo en el
// 8,3% y ninguna cae en fin de mes. Los valores se agrupan en fechas de tanda
// contable. No es derivable: se deja siempre pendiente salvo regla explicita.
const fechaCtbMode = (readString(getVar('CAMPOJOYMA_FECHA_CTB_MODE')) || '').toLowerCase();
const fechaCtb = fechaCtbMode === 'fecha_factura' ? readString(literal.fecha_factura) : null;
if (!fechaCtb) {
  warnings.push('FRR_fechactb requiere seleccion manual: en el historico reciente no se deriva de la fecha de factura ni del fin de mes.');
  requiresConfirmation.push('FRR_fechactb');
}

// ---------------------------------------------------------------- duplicado
const numeroFactura = readString(literal.numero_factura);
let duplicateCount = 0;
let duplicateCandidates = [];
let duplicateCheckStatus = 'skipped';
if (empresaId && ejercicio && providerId && numeroFactura && apiBase) {
  duplicateCheckStatus = 'failed';
  const duplicateResult = await apiGetResult('/facturasrecibidas/buscar', {
    empresa_id: empresaId,
    ejercicio,
    proveedor_id: providerId,
    numero_factura: numeroFactura,
    limit: 10,
  });
  if (duplicateResult.ok && Array.isArray(duplicateResult.data?.items)) {
    const items = itemsFromResponse(duplicateResult.data);
    duplicateCount = readInteger(duplicateResult.data?.total, items.length) ?? items.length;
    duplicateCandidates = items.slice(0, 5).map((item) => ({
      FRR_id: readInteger(item?.FRR_id),
      FRR_numero: readInteger(item?.FRR_numero),
      FRR_numerofactura: readString(item?.FRR_numerofactura),
    }));
    duplicateCheckStatus = 'ok';
    if (duplicateCount > 0) warnings.push('Existe una posible factura duplicada en ERP para empresa, ejercicio, proveedor y numero.');
  } else if (duplicateResult.ok) {
    warnings.push('La respuesta de duplicados no respeta el contrato {items,total}; no se considera comprobada.');
  }
}

// ---------------------------------------------------------------- punteos candidatos
// La fuente dominante en las altas recientes es albentrada_hisgastos, cuyo campo
// Ref viene vacio. Por eso se cruza tambien por Albaran y por importe.
const visibleReferences = new Set((Array.isArray(literal.referencias) ? literal.referencias : []).map(normalizeReference).filter(Boolean));
const lineAmounts = (Array.isArray(literal.lineas) ? literal.lineas : [])
  .map((linea) => readNumber(linea?.importe))
  .filter((value) => value !== null && value !== 0);
const punteosVariable = getVar('CAMPOJOYMA_CARGAR_PUNTEOS');
const loadPunteos = punteosVariable === null ? true : String(punteosVariable).toLowerCase() === 'true';
const allowedPunteoSources = new Set([
  'albsalida_gastos',
  'albentrada_hisgastos',
  'albaranescompra_gastos',
  'facturas_gastos',
  'albarancoste',
  'albmaterial',
]);
let punteoSuggestions = [];
let punteoCandidateCount = 0;
if (loadPunteos && empresaId && providerId && apiBase && (visibleReferences.size > 0 || lineAmounts.length > 0)) {
  const punteosResult = await apiGetResult('/albaranes-gastos/punteables', {
    empresa_id: empresaId,
    proveedor_id: providerId,
    solo_pendientes: true,
    limit: 100,
  });
  if (punteosResult.ok) {
    const allCandidates = itemsFromResponse(punteosResult.data);
    punteoCandidateCount = allCandidates.length;
    const scored = [];
    for (const item of allCandidates) {
      if (!allowedPunteoSources.has(readString(item?.source_table)) || !readPositiveInteger(item?.source_id)) continue;
      if (readPositiveInteger(item?.empresa) !== empresaId || readPositiveInteger(item?.acreedor_id) !== providerId) continue;
      const refs = [item?.Ref, item?.Albaran, item?.source_id].map(normalizeReference).filter(Boolean);
      const porReferencia = refs.some((candidate) => visibleReferences.has(candidate));
      const importe = readNumber(item?.Importe);
      const porImporte = importe !== null && lineAmounts.some((value) => Math.abs(value - importe) <= 0.01);
      if (!porReferencia && !porImporte) continue;
      scored.push({ item, motivo: porReferencia ? 'referencia' : 'importe', peso: porReferencia ? 2 : 1 });
    }
    scored.sort((a, b) => b.peso - a.peso);
    punteoSuggestions = scored.slice(0, 25).map((entry, index) => ({
      posicion: index + 1,
      motivo: entry.motivo,
      remote_id: readString(entry.item?.id_interno_estable),
      source_table: readString(entry.item?.source_table),
      source_id: readPositiveInteger(entry.item?.source_id),
      importe_factura: null,
      Origen: readString(entry.item?.Origen),
      Serie: readString(entry.item?.Serie),
      Albaran: readInteger(entry.item?.Albaran),
      Ref: readString(entry.item?.Ref),
      Fecha: readString(entry.item?.Fecha),
      'Importe P': readNumber(entry.item?.['Importe P'], 0) ?? 0,
      Importe: readNumber(entry.item?.Importe, 0) ?? 0,
      S: false,
      Ver: true,
      empresa_id: readInteger(entry.item?.empresa),
      proveedor_id: readInteger(entry.item?.acreedor_id),
      gasto_id: readInteger(entry.item?.gasto_id),
      gasto_nombre: readString(entry.item?.gasto_nombre),
      cuenta_gasto: readString(entry.item?.cuenta_gasto),
    }));
    if (punteoSuggestions.length > 0) {
      warnings.push('Se han encontrado punteos candidatos; solo se guardan como evidencia y no se envian como punteos.');
    }
  }
}

// ---------------------------------------------------------------- cabecera ERP
const tramos = Array.isArray(literal.tramos_iva) ? literal.tramos_iva.slice(0, 5) : [];
const baseTotal = tramos.reduce((sum, tramo) => sum + (readNumber(tramo?.base) ?? 0), 0);

// Convencion medida en 120/120: el concepto empieza por "FRA" y en el 85,8% es
// exactamente "FRA. " + nombre del acreedor, cortado a 50 caracteres.
const conceptoErp = provider?.nombre ? ('FRA. ' + provider.nombre).slice(0, 50) : null;
const conceptoPdf = readString(literal.concepto);
if (!conceptoErp && conceptoPdf) {
  warnings.push('No se pudo componer FRR_Concepto desde el maestro; queda pendiente de revision.');
}

// Retencion: el porcentaje del maestro coincide con FRR_ret en 69/69 cabeceras
// recientes. El PDF solo sirve para contrastar.
const retencionMaestro = readNumber(provider?.porcentaje_retencion);
const retencionPdf = readNumber(literal.retencion?.porcentaje);
const retencionPct = retencionMaestro !== null ? retencionMaestro : null;
if (retencionMaestro !== null && retencionPdf !== null && Math.abs(retencionMaestro - retencionPdf) > 0.001) {
  warnings.push('El porcentaje de retencion del PDF (' + retencionPdf + '%) no coincide con el del maestro (' + retencionMaestro + '%); se conserva el del maestro.');
}
const baseRet = readNumber(literal.retencion?.base);
const cuotaRet = readNumber(literal.retencion?.cuota);

// Seccion y actividad: coinciden con el maestro en 92,8%; las discrepancias
// observadas son todas de tipo GE, que usa 0/0.
const esGenero = tipoFactura === 'GE';
const seccionId = esGenero ? 0 : readNonNegativeInteger(provider?.seccion_id);
const actividadId = esGenero ? 0 : readNonNegativeInteger(provider?.actividad_id);

// En compras de genero la cuenta del proveedor pertenece a la familia 400...,
// no a la 410... del maestro. Se avisa en vez de reescribirla.
const cuentaProveedor = readString(provider?.cuenta_id);
if (esGenero && cuentaProveedor && cuentaProveedor.startsWith('410')) {
  warnings.push('En compras de genero la cuenta del proveedor suele ser de la familia 400...; el maestro devuelve ' + cuentaProveedor + '. Confirmar antes de enviar.');
  requiresConfirmation.push('FRR_idcuenta');
}

const extraction = {
  document_kind: readString(literal.document_kind),
  moneda: readString(literal.moneda),
  proveedor_nombre: provider?.nombre ?? readString(literal.proveedor_nombre),
  proveedor_nif: provider?.nif ?? readString(literal.proveedor_nif),
  FRR_idproveedor: providerId,
  FRR_idcuenta: readString(provider?.cuenta_id),
  FRR_numerofactura: numeroFactura,
  FRR_fechafactura: readString(literal.fecha_factura),
  FRR_fechactb: fechaCtb,
  FRR_ejercicio: ejercicio,
  FRR_Idempresa: empresaId,
  FRR_idregimen: regimenId,
  FRR_tipofactura: tipoFactura,
  FRR_baseret: baseRet,
  FRR_ret: retencionPct,
  FRR_cuotaret: cuotaRet,
  FRR_totalfac: readNumber(literal.total),
  FRR_Concepto: conceptoErp,
  FRR_ObservacionesAEAT: conceptoErp,
  FRR_Observaciones: readString(literal.observaciones_visibles),
  FRR_Contabilizar: 'N',
  // Constantes verificadas en las 120 cabeceras mas recientes (valor unico).
  FRR_idcentro: 1,
  FRR_idpuntoventa: 1,
  FRR_Modificable: '',
  FRR_CancelarporCtb: 'N',
  FRR_IdTipoDoc: 0,
  FRR_IdAgricultorDto: 0,
  FRR_idpago: 0,
  FRR_IdfacturaRec: 0,
  FRR_CuotaNoDeducible: 0,
  FRR_IdSeccion: seccionId,
  FRR_IdActividad: actividadId,
  lineas: Array.isArray(literal.lineas) ? literal.lineas : [],
  referencias_punteo: Array.isArray(literal.referencias) ? literal.referencias : [],
  evidencias: Array.isArray(literal.evidencias) ? literal.evidencias : [],
};
for (let index = 1; index <= 5; index += 1) {
  const tramo = tramos[index - 1] ?? {};
  extraction['FRR_base' + index] = readNumber(tramo.base);
  extraction['FRR_iva' + index] = readNumber(tramo.porcentaje);
  extraction['FRR_cuota' + index] = readNumber(tramo.cuota);
}

// Vencimientos: el ERP no los almacena. Medido en 120/120 cabeceras recientes,
// FechaVto="0000-00-00", FRR_FechaVto1..3="1900-01-01" e importes a 0. Se
// conservan como evidencia y NO se escriben en los campos ERP.
const vencimientosPdf = (Array.isArray(literal.vencimientos) ? literal.vencimientos : []).slice(0, 4).map((item) => ({
  fecha: readString(item?.fecha),
  importe: readNumber(item?.importe),
}));
if (vencimientosPdf.some((item) => item.fecha || item.importe)) {
  warnings.push('El PDF declara vencimientos; se guardan como evidencia porque el ERP no los almacena en FechaVto/ImporteVto.');
}

// Gastos de cabecera: el ERP rellena FRR_igasto1 en 120/120, y coincide con la
// base en el 69,2%. Se propone como candidato con evidencia, nunca como valor
// definitivo, porque la cuenta correcta depende del tipo (en GE es la del
// agricultor, no la del maestro).
const cuentaGastoMaestro = readString(provider?.cuenta_gasto);
const gastoCandidato = baseTotal > 0
  ? { posicion: 1, importe: Math.round(baseTotal * 100) / 100, cuenta: cuentaGastoMaestro, origen: cuentaGastoMaestro ? 'maestro_acreedor' : 'pendiente' }
  : null;
if (gastoCandidato && !cuentaGastoMaestro) {
  warnings.push('El acreedor no tiene cuenta de gasto en el maestro; FRR_ctagasto1 requiere seleccion manual.');
}
if (esGenero && gastoCandidato) {
  warnings.push('En compras de genero (GE) la cuenta de gasto suele ser la del agricultor (4009...), no la del maestro; requiere confirmacion.');
}

// ---------------------------------------------------------------- evidencia
evidence.empresa = {
  configured_id: configuredEmpresaId,
  source: empresaVariableId ? 'n8n_variable' : 'workflow_default',
  validated: empresaValidated,
};
evidence.ejercicio = { configured: Boolean(ejercicio), value: ejercicio };
evidence.acreedor = {
  resolution: providerReason,
  matched: Boolean(provider),
  provider_id: providerId,
  attempts: providerAttempts,
  cuenta_id: readString(provider?.cuenta_id),
  cuenta_gasto: cuentaGastoMaestro,
  actividad_id: readNonNegativeInteger(provider?.actividad_id),
  seccion_id: readNonNegativeInteger(provider?.seccion_id),
  porcentaje_retencion: retencionMaestro,
};
evidence.historico_proveedor = {
  consultado: Boolean(providerId && apiBase),
  facturas_leidas: historia.length,
  facturas_totales: historiaTotal,
  truncado: historiaTotal !== null && historia.length < historiaTotal,
  iva_principal: ivaPrincipal,
  ivas_observados: [...ivasEnHistoria].sort((a, b) => a - b),
  multi_iva: proveedorMultiIva,
  // Facturas del proveedor cuya base NO esta en el hueco 1: indican que el
  // operador reordena la escalera de IVA y que el regimen no es reconstruible.
  con_base_fuera_del_hueco1: historiaDesalineada,
};
evidence.tipo_factura = {
  source: tipoOrigen,
  value: tipoFactura,
  es_default: tipoOrigen === 'default_campojoyma',
  default_aplicado: DEFAULT_TIPO_FACTURA,
  sugerencia: tipoSugerido.value,
  confianza: tipoSugerido.confianza ?? null,
  muestra: tipoSugerido.total,
  ranking: tipoSugerido.ranking,
};
evidence.regimen = {
  source: regimenOrigen,
  value: regimenId,
  es_default: regimenOrigen === 'default_campojoyma',
  default_aplicado: DEFAULT_REGIMEN_ID,
  sugerencia: regimenSugerido.value,
  confianza: regimenSugerido.confianza ?? null,
  muestra: regimenSugerido.total,
  ranking: regimenSugerido.ranking,
  por_proveedor_iva: { value: regimenPorPar.value, muestra: regimenPorPar.total, confianza: regimenPorPar.confianza ?? null },
  por_proveedor: { value: regimenPorProveedor.value, muestra: regimenPorProveedor.total, confianza: regimenPorProveedor.confianza ?? null },
};
evidence.fecha_ctb = { source: fechaCtb ? 'n8n_variable' : 'pending', value: fechaCtb };
evidence.duplicado = {
  attempted: duplicateCheckStatus !== 'skipped',
  checked: duplicateCheckStatus === 'ok',
  status: duplicateCheckStatus,
  count: duplicateCheckStatus === 'ok' ? duplicateCount : null,
  candidates: duplicateCandidates,
};
evidence.punteos = {
  enabled: loadPunteos,
  source: punteosVariable === null ? 'workflow_default' : 'n8n_variable',
  returned: punteoCandidateCount,
  suggested: punteoSuggestions.length,
  selected: 0,
  candidates: punteoSuggestions,
};
evidence.gastos = { candidato: gastoCandidato, aplicado: false };
evidence.vencimientos_pdf = vencimientosPdf;
evidence.concepto = { erp: conceptoErp, pdf: conceptoPdf, convencion: 'FRA. <acreedor> cortado a 50' };

// ---------------------------------------------------------------- salida
const documentKind = readString(literal.document_kind);
const shouldIngest = ai.ok !== false && ['factura', 'factura_rectificativa', 'abono'].includes(documentKind);
const readyForErp = Boolean(
  shouldIngest && providerId && empresaId && ejercicio && regimenId && tipoFactura && fechaCtb &&
  numeroFactura && extraction.FRR_fechafactura && extraction.FRR_totalfac !== null &&
  duplicateCheckStatus === 'ok' && duplicateCount === 0 && requiresConfirmation.length === 0
);
const finalWarnings = [...new Set(warnings.map(readString).filter(Boolean))];
const finalMetadata = {
  confidence: readNumber(metadata.confidence),
  warnings: finalWarnings,
  raw_text_summary: readString(metadata.raw_text_summary),
  document_kind: documentKind,
  pdf_sha256: readString(source.pdf_sha256),
  extraction_ok: shouldIngest,
  ready_for_review: shouldIngest,
  ready_for_erp: readyForErp,
  requires_confirmation: [...new Set(requiresConfirmation)],
  match_evidence: evidence,
};
const output = { extraction, gastos: [], ctb: [], punteos: [], metadata: finalMetadata };

return { json: {
  ok: shouldIngest,
  should_ingest: shouldIngest,
  request_id: source.request_id,
  trigger_channel: triggerChannel,
  output,
  ingest_payload: shouldIngest ? {
    contract_version: 2,
    request_id: source.request_id,
    trigger_channel: triggerChannel,
    source: triggerChannel === 'email' ? 'campojoyma-email' : 'xfuego-front',
    pdf_base64: source.pdf_base64,
    pdf_nombre: source.pdf_nombre,
    pdf_mime_type: source.pdf_mime_type,
    pdf_size: source.pdf_size,
    email: source.email ?? {},
    extraction,
    gastos: [],
    ctb: [],
    punteos: [],
    metadata: finalMetadata,
  } : null,
} };

const source = $json;
const hash = String(source.pdf_sha256 ?? '').trim().toLowerCase();
if (!/^[0-9a-f]{64}$/.test(hash)) {
  throw new Error('No se pudo calcular un SHA-256 valido del PDF.');
}

let requestId = source.request_id ?? null;
if (!requestId) {
  let hex = hash.slice(0, 32);
  hex = hex.slice(0, 12) + '5' + hex.slice(13);
  const variant = ((parseInt(hex[16], 16) & 0x3) | 0x8).toString(16);
  hex = hex.slice(0, 16) + variant + hex.slice(17);
  requestId = hex.slice(0, 8) + '-' + hex.slice(8, 12) + '-' + hex.slice(12, 16) + '-' + hex.slice(16, 20) + '-' + hex.slice(20, 32);
}

return { json: { ...source, request_id: requestId, pdf_sha256: hash } };

// Reconstruye la respuesta JSON de api-pdf-imagen como binarios reales de n8n.
const serializedBinary = $json.binary;

if (!serializedBinary || typeof serializedBinary !== 'object' || Array.isArray(serializedBinary)) {
  throw new Error('La API PDF-imagen no devolvio el objeto binary esperado.');
}

const requestedKeys = Array.isArray($json.binaryKeys)
  ? $json.binaryKeys
  : Object.keys(serializedBinary);
const binary = {};

for (const key of requestedKeys) {
  const image = serializedBinary[key];
  if (!image || typeof image !== 'object' || typeof image.data !== 'string') {
    throw new Error('La imagen ' + key + ' no contiene data en base64.');
  }

  const cleanBase64 = image.data
    .trim()
    .replace(/^data:[^;]+;base64,/i, '')
    .replace(/\s/g, '');

  if (!cleanBase64 || !/^[A-Za-z0-9+/]*={0,2}$/.test(cleanBase64) || cleanBase64.length % 4 === 1) {
    throw new Error('La imagen ' + key + ' no contiene un base64 valido.');
  }

  const unpadded = cleanBase64.replace(/=+$/, '');
  const padded = unpadded + '='.repeat((4 - (unpadded.length % 4)) % 4);
  const imageBuffer = Buffer.from(padded, 'base64');
  const canonicalBase64 = imageBuffer.toString('base64');

  if (!imageBuffer.length || canonicalBase64.replace(/=+$/, '') !== unpadded) {
    throw new Error('La imagen ' + key + ' no supera la validacion base64.');
  }

  binary[key] = {
    data: canonicalBase64,
    mimeType: typeof image.mimeType === 'string' && image.mimeType ? image.mimeType : 'image/jpeg',
    fileName: typeof image.fileName === 'string' && image.fileName ? image.fileName : key + '.jpg',
    fileExtension: typeof image.fileExtension === 'string' && image.fileExtension ? image.fileExtension : 'jpg',
  };
}

const binaryKeys = Object.keys(binary);
if (binaryKeys.length === 0) {
  throw new Error('La API PDF-imagen no devolvio ninguna pagina.');
}

const { binary: _serializedBinary, ...metadata } = $json;
return {
  json: {
    ...metadata,
    pagesConverted: binaryKeys.length,
    binaryKeys,
  },
  binary,
};

const kind = $json.output?.metadata?.document_kind ?? 'desconocido';
const warnings = Array.isArray($json.output?.metadata?.warnings) ? $json.output.metadata.warnings.join(' | ') : '';
throw new Error('Documento de email no ingerido. Tipo: ' + kind + (warnings ? '. ' + warnings : ''));

const expectedRequestId = $('Preparar respuesta Edge').item.json.ingest_payload.request_id;
const results = Array.isArray($json.results) ? $json.results : [];
const result = results[0] ?? {};
if (
  $json.success !== true ||
  Number($json.facturas_created ?? 0) !== 1 ||
  results.length !== 1 ||
  result.request_id !== expectedRequestId ||
  !result.factura_id
) {
  const errors = Array.isArray($json.errors) ? $json.errors.map((item) => item?.error).filter(Boolean).join(' | ') : '';
  throw new Error('La Edge de ingesta no confirmo exactamente una factura para el request_id esperado.' + (errors ? ' ' + errors : ''));
}
return { json: {
  contract_version: $json.contract_version,
  success: true,
  request_id: result.request_id,
  factura_id: result.factura_id,
  estado: result.estado,
  archivo_pdf_id: result.archivo_pdf_id,
  version: result.version,
  validation_errors: result.validation_errors ?? [],
} };

const item = $json ?? {};
const raw = item.error ?? item.message ?? item;
const message = typeof raw === 'string'
  ? raw
  : (raw?.message ?? raw?.description ?? 'Fallo no identificado durante la extraccion.');
const canal = item.trigger_channel
  ?? item.source?.trigger_channel
  ?? (item.source === 'campojoyma-email' ? 'email' : 'webhook');
return { json: {
  contract_version: 2,
  ok: false,
  request_id: item.request_id ?? item.source?.request_id ?? null,
  trigger_channel: canal,
  error: String(message).slice(0, 500),
  node: item.node ?? null,
} };
